<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import MobileAccess from './MobileAccess.vue'
import {localManagement,desktopManagement,operatorRequest,restoreBackup,retentionPreview,serviceAction,type Backup,type Retention} from './systemManagement'
const local=computed(localManagement),backups=ref<Backup[]>([]),busy=ref(false),error=ref(''),message=ref(''),uncertain=ref(false),filename=ref(''),typedBackup=ref(''),restoreConsent=ref(false),backupConsent=ref(false),retentionDays=ref(0),retention=ref<Retention>(),service=ref<'restart'|'shutdown'>('restart'),typedService=ref(''),serviceConsent=ref(false),serviceRequested=ref(false)
let alive=true,revision=0
const desktop=computed(desktopManagement)
async function read(){const n=++revision;busy.value=true;error.value='';uncertain.value=false;backups.value=[];retention.value=undefined;restoreConsent.value=false;typedBackup.value='';backupConsent.value=false;serviceConsent.value=false;typedService.value='';try{if(!local.value)return;const data=await operatorRequest<{backups:Backup[]}>('/api/backups','GET',undefined,true);if(!alive||n!==revision)return;backups.value=data.backups;if(!backups.value.some(b=>b.filename===filename.value))filename.value=''}catch(e){if(alive&&n===revision)error.value=(e as Error).message}finally{if(alive&&n===revision)busy.value=false}}
async function write(action:()=>Promise<unknown>,text:string,refresh=true){if(busy.value||uncertain.value||serviceRequested.value)return;busy.value=true;error.value='';const n=revision;try{const result=await action();if(!alive||n!==revision)return;message.value=text;if(refresh)await read();return result}catch{if(alive&&n===revision){error.value='操作结果未能确认，请先核实服务器状态；不自动重复操作。';uncertain.value=true}}finally{if(alive)busy.value=false}}
async function restore(){const r=await write(()=>restoreBackup(filename.value,typedBackup.value,restoreConsent.value),'恢复已完成；请重新登录/刷新数据，并按提示手动重启。') as {message:string;safety_backup:string}|undefined;if(alive&&r)message.value=r.message+'；恢复前安全备份：'+r.safety_backup}
async function preview(){const n=revision;busy.value=true;error.value='';retention.value=undefined;try{const r=await retentionPreview(Number(retentionDays.value));if(!alive||n!==revision)return;if(r.deletion_performed)throw new Error('服务端报告了非预期删除，请停止操作并核实。');retention.value=r}catch(e){if(alive&&n===revision)error.value=(e as Error).message}finally{if(alive&&n===revision)busy.value=false}}
async function control(){const r=await write(()=>serviceAction(service.value,typedService.value,serviceConsent.value),'服务操作已提交；请等待当前任务完成后手动刷新或重新打开程序。',false);if(alive&&r)serviceRequested.value=true}
onMounted(read);onUnmounted(()=>{alive=false;revision++;backups.value=[];retention.value=undefined})
</script>
<template><section aria-label="本机运维管理"><h3>备份、保留预览与本机服务</h3><p><a href="/api/diagnostics-export">导出诊断包</a>（仅版本、计数和筛选后的审计类型，不含学生数据、密钥或路径）</p><p v-if="!local">这些操作仅在本机模式开放；云端继续通过既有运维入口处理。</p><template v-else><button @click="read" :disabled="busy||serviceRequested">刷新备份状态</button><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
 <fieldset :disabled="busy||uncertain||serviceRequested"><legend>数据库与照片备份</legend><label class="check"><input type="checkbox" v-model="backupConsent">确认创建当前数据备份（不含API Key）</label><button @click="backupConsent&&write(()=>operatorRequest('/api/backup/create','POST',{},true),'备份已创建。')" :disabled="!backupConsent">创建本机备份</button><label for="system-backup">选择已有备份</label><select id="system-backup" v-model="filename" @change="restoreConsent=false;typedBackup=''"><option value="">请选择</option><option v-for="b in backups" :key="b.filename" :value="b.filename">{{ b.created_at }} · {{ b.filename }} · {{ b.bytes }}字节</option></select><p>恢复会替换当前数据库和照片，服务端将先创建恢复前安全备份。不要在评分/上传中恢复。</p><label>输入完整备份文件名<input v-model="typedBackup" @input="restoreConsent=false"></label><label class="check"><input type="checkbox" v-model="restoreConsent">确认用所选备份替换当前数据</label><button @click="restore" :disabled="!filename||typedBackup!==filename||!restoreConsent">恢复选中备份</button></fieldset>
 <fieldset :disabled="busy||uncertain||serviceRequested"><legend>照片保留期限预览</legend><label>保留天数（0—3650，仅预览）<input v-model.number="retentionDays" type="number" min="0" max="3650" step="1"></label><button @click="preview">仅预览保留候选</button><p v-if="retention">原图{{ retention.total_original_images }} · 模拟候选{{ retention.hypothetical_eligible_images }} · 保留{{ retention.held_images }}；dry-run，未删除。{{ retention.held_reason }}</p></fieldset>
 <MobileAccess :closable="false"/>
 <fieldset v-if="desktop" :disabled="busy||uncertain||serviceRequested"><legend>本机服务控制</legend><p>这会中断当前连接；程序等待当前任务结束后再执行。云端运维不使用此入口。</p><label for="local-service-action">本机服务操作</label><select id="local-service-action" v-model="service" @change="typedService='';serviceConsent=false"><option value="restart">重启</option><option value="shutdown">停止</option></select><label>输入确认文字（重启或停止）<input v-model="typedService" @input="serviceConsent=false"></label><label class="check"><input type="checkbox" v-model="serviceConsent">确认执行所选本机服务操作</label><button @click="control" :disabled="!serviceConsent||typedService!==(service==='restart'?'重启':'停止')">提交本机服务操作</button></fieldset>
 </template></section></template>
